    """The connected non-background components as (color, cells) ordered by their leftmost column."""
    h, w = len(grid), len(grid[0])
    seen = [[False]*w for _ in range(h)]; out = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] and not seen[i][j]:
                c = grid[i][j]; stack = [(i, j)]; cells = []
                seen[i][j] = True
                while stack:
                    y, x = stack.pop(); cells.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == c:
                            seen[ny][nx] = True; stack.append((ny, nx))
                out.append((c, cells))
    out.sort(key=lambda s: min(x for _, x in s[1]))
    return out

def cascade(grid):
    """Shapes restacked from the top-left: each next shape\'s top-left corner on the previous shape\'s bottom-right corner, later shapes overwriting earlier."""
    out = [[0]*len(grid[0]) for _ in grid]
    top = left = 0
    for k, (c, cells) in enumerate(shapes(grid)):
        if k:
            ys = [y for y, _ in cells]; xs = [x for _, x in cells]
            h, w = max(ys)-min(ys)+1, max(xs)-min(xs)+1
            top, left = top+h-1, left+w-1
        for y, x in cells:
            out[top+y-min(y for y,_ in cells)][left+x-min(x for _,x in cells)] = c
    return out
